INSERT INTO billing_plans(id,name,price_vnd,days,features) VALUES('consultation','Tư vấn riêng qua Zalo',0,1,'["private-consultation"]');
CREATE TABLE consultation_config (plan_id VARCHAR(32) PRIMARY KEY REFERENCES billing_plans(id), advisor VARCHAR(100) NOT NULL DEFAULT '', zalo_phone VARCHAR(15) NOT NULL DEFAULT '', scope VARCHAR(2000) NOT NULL DEFAULT '', response_hours INTEGER NOT NULL DEFAULT 48 CHECK(response_hours BETWEEN 1 AND 720), question_limit INTEGER NOT NULL DEFAULT 3 CHECK(question_limit BETWEEN 1 AND 20));
INSERT INTO consultation_config(plan_id) VALUES('consultation');
CREATE TABLE consultation_requests (order_id UUID PRIMARY KEY REFERENCES billing_orders(id), chart_id UUID REFERENCES charts(id) ON DELETE SET NULL, chart_snapshot JSONB NOT NULL, question TEXT NOT NULL CHECK(length(question) BETWEEN 1 AND 2000), advisor VARCHAR(100) NOT NULL, zalo_phone VARCHAR(15) NOT NULL, scope VARCHAR(2000) NOT NULL, response_hours INTEGER NOT NULL, question_limit INTEGER NOT NULL, service_status VARCHAR(20) NOT NULL DEFAULT 'waiting' CHECK(service_status IN ('waiting','in_progress','completed')), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
